// Forms sends two emails at submit: "ID Setup Required" (to grp.forms.idsetup) and "Request Submitted" (to the requester).
// Since 2026-09-23 both carry the Request ID (NEW_EMP_…) and the pre-assigned Internal ID in Request Details. Read them off the email.
const m = $input.first().json;
const html = String(m.html || m.text || m.snippet || '');
const text = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
const wfFromLink = (html.match(/[?&]wf=(NEW_EMP_[A-Za-z0-9_-]+)/) || [])[1];         // ID Setup Required: the form button URL
const wfFromRow  = (text.match(/Request ID\s*(NEW_EMP_[A-Za-z0-9_-]+)/) || [])[1];   // both emails: the Request ID row
const workflowId = wfFromLink || wfFromRow || '';
if (!workflowId) return [];                                                           // not a New Hire submit email — ignore
const internalIdFromEmail = (text.match(/Internal ID\s*(\d{4,6})\b/) || [])[1] || '';
const employeeNameFromEmail = ((text.match(/Employee\s+(.+?)\s+(?:Request ID|Internal ID|Type |Job Title)/) || [])[1] || '').trim();
// Dedupe: a requester who is also in the ID Setup group receives BOTH emails for one hire.
const sd = $getWorkflowStaticData('global'); sd.seen = sd.seen || {}; const now = Date.now();
for (const k of Object.keys(sd.seen)) if (now - sd.seen[k] > 7 * 864e5) delete sd.seen[k];
if (sd.seen[workflowId]) return [];
sd.seen[workflowId] = now;
return [{ json: { workflowId, internalIdFromEmail, employeeNameFromEmail, subject: String(m.subject || ''), messageId: String(m.id || '') } }];

// George's step 3: draft the SiteDocs / DSS / BOSS setup, then ask for approval.
// Input = Forms · Get Workflow (PROD), flattened: requestData (sheet headers as keys), employeeId {internalEmployeeId}, checklist[], status.
const g  = $input.first().json;
const p  = $('Parse submit email').first().json;
const rd = g.requestData || {};
const id = String((g.employeeId && g.employeeId.internalEmployeeId) || rd['Internal Employee ID'] || p.internalIdFromEmail || '');
if (!id) throw new Error('No Internal Employee ID for ' + p.workflowId + ' (it is minted at submit — check the Employee IDs tab)');
if (String(g.status || '') === 'Cancelled') throw new Error(p.workflowId + ' is Cancelled — nothing to set up');
const first = String(rd['First Name'] || '').trim(), last = String(rd['Last Name'] || '').trim();
const employmentType = String(rd['Employment Type'] || '');
const out = {
  workflowId: p.workflowId, internalEmployeeId: id,
  employeeName: (first + ' ' + last).trim() || p.employeeNameFromEmail,
  employmentType, positionTitle: String(rd['Position Title'] || ''), siteName: String(rd['Site Name'] || ''),
  hireDate: String(rd['Hire Date'] || ''), managerEmail: String(rd['Manager Email'] || ''), systemAccess: String(rd['System Access'] || ''),
  // ---- DRAFTED, NOT CREATED. George: replace these with the real SiteDocs / DSS / BOSS calls; keep the output keys. ----
  siteDocsWorkerId: 'SD-' + id,
  siteDocsJobCode: /salary/i.test(employmentType) ? 'Salary 1' : 'Hourly 1',   // strict enum: Hourly 1 | Hourly 2 | Salary 1 | Salary 2 | Supervisor | Manager
  dssUsername: ((first[0] || 'x') + (last[0] || 'x')).toLowerCase() + id,
  dssPassword: 'Temp-' + Math.random().toString(36).slice(2, 10) + '!'
};
// Survive the approval wait: node data from before a Wait-resume is not reachable afterwards, so stash it by execution id.
const sd = $getWorkflowStaticData('global'); sd.drafts = sd.drafts || {}; const now = Date.now();
for (const k of Object.keys(sd.drafts)) if (now - (sd.drafts[k]._at || 0) > 7 * 864e5) delete sd.drafts[k];
sd.drafts['x' + $execution.id] = Object.assign({ _at: now }, out);
return [{ json: out }];

// After the approval click. Read the stashed draft (pre-wait node data is unavailable after a Wait resume).
const sd = $getWorkflowStaticData('global');
const d = (sd.drafts || {})['x' + $execution.id];
if (!d) throw new Error('No stashed draft for execution ' + $execution.id + ' — the run started before the stash existed, or it expired');
return [{ json: {
  workflowId: d.workflowId,
  siteDocsWorkerId: d.siteDocsWorkerId, siteDocsJobCode: d.siteDocsJobCode,
  dssUsername: d.dssUsername, dssPassword: d.dssPassword,
  setupNotes: 'Submitted by n8n after approval (ID Setup from submit email)',
  actor: { id: 'n8n:idsetup-from-email', email: 'efx-bot@team-group.com', display: 'ID Setup from submit email (n8n)' },
  _employeeName: d.employeeName, _internalEmployeeId: d.internalEmployeeId
} }];
